def item(i, *, detail=True):
    x = ITEMS[i]
    result = (f'<p class="demo-result" data-result hidden>{esc(x["hidden"])}</p>' if x['hidden'] else '')
    evidence = f'''<details><summary>Source and freshness</summary><p><strong>Source:</strong> synthetic-demo. Independently authored demo, not provider data.<br><strong>Observed:</strong> {x['observed']}<br><strong>Event:</strong> {x['event']}<br><strong>Snapshot:</strong> Oct 10, 12:00 UTC. Demo times are fixed here, not a live refresh.<br><strong>Why selected:</strong> {x['why']}.</p></details>''' if detail else ''
    return f'''<article class="item"><div class="item-meta"><span class="tag demo">DEMO / SYNTHETIC</span><span class="tag">{x['tier'].replace('_',' ')}</span></div><p class="meta">{esc(x['entity'])}</p><h3>{esc(x['title'])}</h3><p class="summary">Demo data: {esc(x['summary'])}.</p>{result}<p class="when">{x['time']}</p><p class="rationale">{x['why']}.</p>{evidence}</article>'''

UNAVAILABLE = '<aside class="unavailable"><h3>Arsenal · Unavailable</h3><p>Public display and caching permission is unresolved. No Arsenal provider data appears here.</p></aside>'
COVERAGE = '<div class="coverage"><span>Arsenal · unavailable</span><span>Texans · 2 demo items</span><span>Scottie · 2 demo items</span></div>'

def layout(style):
    if style == 'quiet':
        return UNAVAILABLE + ''.join(f'<h2 class="entity-heading">{name}</h2><div class="group">{item(a)}{item(b)}</div>' for name,a,b in [('Houston Texans',0,3),('Scottie Scheffler',1,2)])
    if style == 'editorial':
        return f'<div class="lead-item">{item(0)}</div><div class="columns"><div>{item(1)}{item(2)}</div><div>{item(3)}{UNAVAILABLE}</div></div>'
    if style == 'priority':
        return ''.join(f'<div class="rank-row"><span class="ordinal">{i+1}</span>{item(i)}</div>' for i in range(4)) + UNAVAILABLE
    if style == 'tabs':
        return '<div class="entity-tabs" aria-label="Choose entity">'+''.join(f'<button data-tab="{k}" aria-pressed="{str(k=="texans").lower()}">{n}</button>' for k,n in [('texans','Houston Texans'),('scheffler','Scottie Scheffler'),('arsenal','Arsenal · unavailable')])+'</div>'+''.join(f'<section class="entity-panel" data-panel="{k}" {"hidden" if k!="texans" else ""}><h2>{n}</h2>{contents}</section>' for k,n,contents in [('texans','Houston Texans',item(0)+item(3)),('scheffler','Scottie Scheffler',item(1)+item(2)),('arsenal','Arsenal',UNAVAILABLE)])
    if style == 'agenda':
        return f'<div class="agenda-lead"><p class="entity-heading">Highest priority now</p>{item(0)}</div>'+''.join(f'<div class="day"><div class="date">{date}<p class="meta">UTC · synthetic</p></div><div>{item(i)}</div></div>' for date,i in [('Oct 9 · completed',1),('Oct 12 · next round',2),('Oct 13 · next game',3)])+UNAVAILABLE
    if style == 'matrix':
        return '<table class="matrix-table"><thead><tr><th>Entity / source state</th><th>Current priority</th><th>Next context</th></tr></thead><tbody><tr><td data-label="Entity / source state"><strong>Houston Texans</strong><p>Demo only · 2 items</p></td><td data-label="Current priority">'+item(0)+'</td><td data-label="Next context">'+item(3)+'</td></tr><tr><td data-label="Entity / source state"><strong>Scottie Scheffler</strong><p>Demo only · 2 items</p></td><td data-label="Current priority">'+item(1)+'</td><td data-label="Next context">'+item(2)+'</td></tr><tr><td data-label="Entity / source state"><strong>Arsenal</strong><p>Unavailable</p></td><td data-label="Current priority" colspan="2">Public display and caching permission is unresolved. No selected public item.</td></tr></tbody></table>'
    if style == 'focus':
        return '<div class="deck">'+''.join(f'<div class="deck-panel" data-slide="{i}" {"hidden" if i else ""}>{item(i)}</div>' for i in range(4))+'</div><div class="deck-nav"><button id="previous" disabled>Previous item</button><span class="progress" id="progress" aria-live="polite">1 of 4</span><button id="next">Next item</button></div>'+UNAVAILABLE
    if style == 'split':
        return '<div class="desk"><div class="headlines" aria-label="Choose ranked item">'+''.join(f'<button data-read="{i}" aria-pressed="{str(i==0).lower()}"><small>{i+1} · {esc(x["entity"])}</small>{esc(x["title"])}</button>' for i,x in enumerate(ITEMS))+'</div><div class="reading">'+''.join(f'<div class="reading-panel" data-reading="{i}" {"hidden" if i else ""}>{item(i)}</div>' for i in range(4))+'</div></div>'+UNAVAILABLE
    if style == 'inbox':
        return ''.join(f'<details class="inbox-row" {"open" if i==0 else ""}><summary><span>{esc(x["title"])}<small>{esc(x["entity"])} · {x["time"]}</small></span><span class="tag">{x["tier"].replace("_"," ")}</span></summary>{item(i)}</details>' for i,x in enumerate(ITEMS))+UNAVAILABLE
    return '<p class="salutation">A short note on the teams and player you follow</p><p>This design-only briefing has four selected synthetic items. Start with the meaningful change, then the recent result, then upcoming context.</p>'+''.join(item(i) for i in range(4))+'<h2 class="entity-heading">What is quiet</h2>'+UNAVAILABLE+'<p class="muted">A quiet entity can have zero items. The page never needs to fill a slot.</p>'

